-- Candidate review is append-only and scoped to one frozen inference candidate.
CREATE TABLE IF NOT EXISTS enrichment.metadata_occupation_candidate_decision (
 decision_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 candidate_id text NOT NULL REFERENCES enrichment.metadata_occupation_candidate,
 decision text NOT NULL CHECK(decision IN('ACCEPT','REJECT')),
 reviewer text NOT NULL CHECK(length(btrim(reviewer))>0),
 reviewer_kind text NOT NULL CHECK(reviewer_kind IN('human','assistant')),
 notes text NOT NULL CHECK(length(btrim(notes))>0),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS metadata_occupation_candidate_decision_latest
 ON enrichment.metadata_occupation_candidate_decision(candidate_id,decision_id DESC);
-- Canonical fresh installation may precede retention. Replay 037 after the
-- retention installer, as the inferred workflow requires before execution.
DO $$ BEGIN
 IF to_regprocedure('retention.freeze_writes()') IS NOT NULL THEN
  CREATE OR REPLACE TRIGGER retention_freeze BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON enrichment.metadata_occupation_candidate_decision
   FOR EACH STATEMENT EXECUTE FUNCTION retention.freeze_writes();
 END IF;
END $$;
DROP TRIGGER IF EXISTS immutable_metadata_occupation_candidate_decision ON enrichment.metadata_occupation_candidate_decision;
CREATE TRIGGER immutable_metadata_occupation_candidate_decision BEFORE UPDATE OR DELETE ON enrichment.metadata_occupation_candidate_decision
 FOR EACH ROW EXECUTE FUNCTION enrichment.reject_metadata_occupation_change();
DROP TRIGGER IF EXISTS immutable_truncate_metadata_occupation_candidate_decision ON enrichment.metadata_occupation_candidate_decision;
CREATE TRIGGER immutable_truncate_metadata_occupation_candidate_decision BEFORE TRUNCATE ON enrichment.metadata_occupation_candidate_decision
 FOR EACH STATEMENT EXECUTE FUNCTION enrichment.reject_metadata_occupation_change();

CREATE OR REPLACE FUNCTION enrichment.guard_metadata_occupation_candidate_decision()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r record;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=TG_RELID AND tgname='retention_freeze'
  AND tgenabled='O' AND tgfoid=to_regprocedure('retention.freeze_writes()'))
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REINSTALL_FOR_RETENTION_GUARD_REQUIRED'; END IF;
 SELECT result.actor,result.item_id,b.settings->>'prompt_version' AS prompt_version,x.job_run_id,x.ncs_run_id INTO STRICT r
 FROM enrichment.metadata_occupation_candidate c JOIN enrichment.metadata_occupation_result result USING(result_id)
 JOIN enrichment.item i USING(item_id) JOIN enrichment.batch b USING(batch_id)
 JOIN enrichment.metadata_occupation_binding x ON x.item_id=i.item_id WHERE c.candidate_id=NEW.candidate_id;
 IF r.prompt_version<>'ko-metadata-occupation-v3' THEN RAISE EXCEPTION 'METADATA_OCCUPATION_LEGACY_RESULT_REVIEW_REQUIRED'; END IF;
 IF NEW.reviewer=r.actor THEN RAISE EXCEPTION 'METADATA_OCCUPATION_INDEPENDENT_REVIEW_REQUIRED'; END IF;
 PERFORM enrichment.verify_item_input(r.item_id);
 IF NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='jobkorea' AND run_id=r.job_run_id)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='ncs_competency' AND run_id=r.ncs_run_id)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REVIEW_SNAPSHOT_STALE'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER metadata_candidate_review_guard BEFORE INSERT ON enrichment.metadata_occupation_candidate_decision
 FOR EACH ROW EXECUTE FUNCTION enrichment.guard_metadata_occupation_candidate_decision();

CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_output_issues_v3(
 output jsonb,source jsonb,candidates jsonb,max_matches integer DEFAULT 3)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE issues jsonb:='[]'; base jsonb; m jsonb; anchor jsonb; fields jsonb:=enrichment.metadata_occupation_fields(source);
 ordinal integer:=0; previous_field text; previous_end integer:=0; start_at integer; n integer;
BEGIN
 IF jsonb_typeof(output->'matches') IS DISTINCT FROM 'array'
 THEN RETURN '["METADATA_OCCUPATION_OUTPUT_SHAPE"]'::jsonb; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(output->'matches') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object')
 THEN RETURN '["METADATA_OCCUPATION_MATCH_SHAPE"]'::jsonb; END IF;
 n:=jsonb_array_length(output->'matches');
 IF max_matches IS NULL OR max_matches NOT BETWEEN 1 AND 3 OR n>max_matches
 THEN issues:=issues||'["METADATA_OCCUPATION_MATCH_CAP"]'::jsonb; END IF;
 -- Delegate literal source quotations, duplicates and outcome/shape checks to
 -- the frozen legacy validator, stripping only the two new match properties.
 SELECT jsonb_set(output,'{matches}',coalesce(jsonb_agg(value-ARRAY['match_rank','role_anchor'] ORDER BY pos),'[]'))
 INTO base FROM jsonb_array_elements(output->'matches') WITH ORDINALITY x(value,pos);
 issues:=issues||(enrichment.metadata_occupation_output_issues(base,source,candidates,2)-'METADATA_OCCUPATION_MATCH_CAP');
 IF n=0 THEN RETURN issues; END IF;
 -- Role alternatives are conservative lexical guards. Tool choices such as
 -- Java or Kotlin cannot disqualify an otherwise explicit single role.
 IF EXISTS(SELECT 1 FROM jsonb_each_text(fields) WHERE key IN('title','role') AND
  lower(value) ~ '(developer|engineer|analyst|administrator|backend|frontend|dba|개발자|분석가|관리자).{0,15}([[:space:]]or[[:space:]]|또는|혹은).{0,30}(developer|engineer|analyst|administrator|backend|frontend|dba|개발자|분석가|관리자)|채용하지|not[[:space:]]+hiring([^a-z]|$)')
 THEN issues:=issues||'["METADATA_OCCUPATION_ALTERNATIVE_OR_CONTRADICTORY_ROLES"]'::jsonb; END IF;
 FOR m IN SELECT value FROM jsonb_array_elements(output->'matches') LOOP
  ordinal:=ordinal+1; anchor:=m->'role_anchor';
  IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR
   NOT m ?& ARRAY['occupation_code','reason','evidence','match_rank','role_anchor'] OR
   m-ARRAY['occupation_code','reason','evidence','match_rank','role_anchor']<>'{}'::jsonb OR
   jsonb_typeof(m->'match_rank') IS DISTINCT FROM 'number' OR m->>'match_rank' IS DISTINCT FROM ordinal::text
  THEN issues:=issues||'["METADATA_OCCUPATION_MATCH_RANK"]'::jsonb; END IF;
  IF jsonb_typeof(anchor) IS DISTINCT FROM 'object' OR
   NOT anchor ?& ARRAY['field','quote'] OR anchor-ARRAY['field','quote']<>'{}'::jsonb OR
   jsonb_typeof(anchor->'field') IS DISTINCT FROM 'string' OR
   anchor->>'field' NOT IN('title','role') OR
   jsonb_typeof(anchor->'quote') IS DISTINCT FROM 'string' OR length(btrim(anchor->>'quote'))<2 OR
   NOT fields ? (anchor->>'field') OR
   coalesce(position(anchor->>'quote' in fields->>(anchor->>'field')),0)=0
  THEN issues:=issues||'["METADATA_OCCUPATION_ROLE_ANCHOR_REQUIRED"]'::jsonb; CONTINUE; END IF;
  IF jsonb_typeof(m->'evidence') IS DISTINCT FROM 'array' OR NOT (m->'evidence') @> jsonb_build_array(anchor)
  THEN issues:=issues||'["METADATA_OCCUPATION_INDEPENDENT_ROLE_EVIDENCE"]'::jsonb; END IF;
  start_at:=position(anchor->>'quote' in fields->>(anchor->>'field'));
  IF ordinal>1 AND (anchor->>'field' IS DISTINCT FROM previous_field OR start_at<=previous_end)
  THEN issues:=issues||'["METADATA_OCCUPATION_DISTINCT_ORDERED_ROLE_ANCHORS"]'::jsonb; END IF;
  IF ordinal>1 AND anchor->>'field'=previous_field AND start_at>previous_end AND
   lower(substring(fields->>previous_field FROM previous_end+1 FOR start_at-previous_end-1)) ~ '(^|[^a-z])or([^a-z]|$)|또는|혹은'
  THEN issues:=issues||'["METADATA_OCCUPATION_ALTERNATIVE_OR_CONTRADICTORY_ROLES"]'::jsonb; END IF;
  previous_field:=anchor->>'field'; previous_end:=start_at+length(anchor->>'quote')-1;
  IF lower(m->>'reason') ~ '(ambiguous|unclear|insufficient|cannot.{0,8}identify|모호|불명확|근거.{0,8}부족|판단.{0,8}어렵)'
  THEN issues:=issues||'["METADATA_OCCUPATION_AMBIGUOUS_MATCH"]'::jsonb; END IF;
 END LOOP;
 RETURN issues;
END $$;

CREATE OR REPLACE FUNCTION enrichment.decide_metadata_occupation_candidate(
 candidate text,decision text,reviewer text,kind text,notes text)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE c enrichment.metadata_occupation_candidate%ROWTYPE; r enrichment.metadata_occupation_result%ROWTYPE;
 binding enrichment.metadata_occupation_binding%ROWTYPE; old enrichment.metadata_occupation_candidate_decision%ROWTYPE; id bigint;
BEGIN
 PERFORM retention.gate();
 SELECT * INTO STRICT c FROM enrichment.metadata_occupation_candidate WHERE candidate_id=candidate FOR UPDATE;
 SELECT * INTO STRICT r FROM enrichment.metadata_occupation_result WHERE result_id=c.result_id;
 SELECT * INTO STRICT binding FROM enrichment.metadata_occupation_binding WHERE item_id=r.item_id;
 PERFORM enrichment.verify_item_input(r.item_id);
 IF NOT EXISTS(SELECT 1 FROM enrichment.item i JOIN enrichment.batch b USING(batch_id)
  WHERE i.item_id=r.item_id AND b.settings->>'prompt_version'='ko-metadata-occupation-v3')
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_LEGACY_RESULT_REVIEW_REQUIRED'; END IF;
 IF decision IS NULL OR decision NOT IN('ACCEPT','REJECT') OR kind IS NULL OR kind NOT IN('human','assistant')
  OR nullif(btrim(reviewer),'') IS NULL OR nullif(btrim(notes),'') IS NULL
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REVIEW_PROVENANCE_REQUIRED'; END IF;
 IF reviewer=r.actor THEN RAISE EXCEPTION 'METADATA_OCCUPATION_INDEPENDENT_REVIEW_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='jobkorea' AND run_id=binding.job_run_id)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='ncs_competency' AND run_id=binding.ncs_run_id)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REVIEW_SNAPSHOT_STALE'; END IF;
 SELECT * INTO old FROM enrichment.metadata_occupation_candidate_decision WHERE candidate_id=candidate ORDER BY decision_id DESC LIMIT 1;
 IF FOUND AND old.decision=decision AND old.reviewer=reviewer AND old.reviewer_kind=kind AND old.notes=notes
 THEN RETURN old.decision_id; END IF;
 INSERT INTO enrichment.metadata_occupation_candidate_decision(candidate_id,decision,reviewer,reviewer_kind,notes)
 VALUES(candidate,decision,reviewer,kind,notes) RETURNING decision_id INTO id;
 RETURN id;
END $$;

-- Latest captured result wins only after complete validation. An unsent or
-- failed successor cannot hide a previously validated occupation projection.
CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_publication_results(jobs text,ncs text)
RETURNS TABLE(posting_id text,item_id text,result_id text) LANGUAGE sql STABLE AS $$
 SELECT DISTINCT ON(i.posting_id) i.posting_id,i.item_id,r.result_id
 FROM enrichment.metadata_occupation_binding x JOIN enrichment.item i USING(item_id)
 JOIN enrichment.batch b USING(batch_id) JOIN enrichment.metadata_occupation_result r USING(item_id)
 WHERE x.job_run_id=jobs AND x.ncs_run_id=ncs
 ORDER BY i.posting_id,b.created_at DESC,i.item_id DESC
$$;

CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_candidate_status(result text)
RETURNS TABLE(candidate_id text,match_rank integer,decision text,decision_id bigint,reviewer text,reviewer_kind text,notes text)
LANGUAGE sql STABLE AS $$
 SELECT c.candidate_id,(m.value->>'match_rank')::integer,d.decision,d.decision_id,d.reviewer,d.reviewer_kind,d.notes
 FROM enrichment.metadata_occupation_candidate c JOIN enrichment.metadata_occupation_result r USING(result_id)
 JOIN enrichment.item i USING(item_id) JOIN enrichment.batch b USING(batch_id)
 CROSS JOIN LATERAL jsonb_array_elements(r.output->'matches') m(value)
 LEFT JOIN LATERAL (SELECT d.* FROM enrichment.metadata_occupation_candidate_decision d
  WHERE d.candidate_id=c.candidate_id ORDER BY d.decision_id DESC LIMIT 1) d ON true
 WHERE c.result_id=result AND b.settings->>'prompt_version'='ko-metadata-occupation-v3'
  AND m.value->>'occupation_code'=c.occupation_code
$$;

CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_graph_rows_v3(jobs text,ncs text,include_unreviewed boolean DEFAULT false)
RETURNS TABLE(posting_id text,posting_identity text,occupation_identity text,candidate_id text,payload jsonb)
LANGUAGE sql STABLE AS $$
 WITH selected AS (
 SELECT s.posting_id,i.item_id,i.batch_id,r.result_id,r.attempt_id,r.actor,c.candidate_id,c.occupation_code,c.reason,c.evidence,
  binding.bundle_id,binding.source_hash,binding.binding_hash,cat.occupation_name,cat.catalog_hash,
  b.settings,a.actual_model,ib.manifest,d.match_rank,d.decision,d.decision_id,d.reviewer,d.reviewer_kind,d.notes,m.value AS match
 FROM enrichment.metadata_occupation_publication_results(jobs,ncs) s
 JOIN enrichment.metadata_occupation_result r ON r.result_id=s.result_id
 JOIN enrichment.metadata_occupation_binding binding ON binding.item_id=s.item_id
 JOIN enrichment.item i ON i.item_id=binding.item_id JOIN enrichment.batch b ON b.batch_id=i.batch_id
 JOIN enrichment.attempt a ON a.attempt_id=r.attempt_id JOIN enrichment.input_bundle ib ON ib.bundle_id=binding.bundle_id
 JOIN enrichment.metadata_occupation_candidate c ON c.result_id=r.result_id
 JOIN enrichment.metadata_occupation_catalog cat ON cat.ncs_run_id=c.ncs_run_id AND cat.occupation_code=c.occupation_code
 JOIN enrichment.metadata_occupation_candidate_status(r.result_id) d ON d.candidate_id=c.candidate_id
 CROSS JOIN LATERAL jsonb_array_elements(r.output->'matches') m(value)
 WHERE b.settings->>'prompt_version'='ko-metadata-occupation-v3' AND r.output->>'outcome'='matched'
  AND m.value->>'occupation_code'=c.occupation_code AND d.decision IS DISTINCT FROM 'REJECT'
  AND (d.decision='ACCEPT' OR include_unreviewed)
  AND EXISTS(SELECT 1 FROM ingestion.run WHERE source_id='jobkorea' AND run_id=jobs AND state='READY')
  AND EXISTS(SELECT 1 FROM ingestion.run WHERE source_id='ncs_competency' AND run_id=ncs AND state='READY')
 ) SELECT s.posting_id,'source:posting:jobkorea:'||enrichment.hash(s.manifest#>>'{document,source_record_id}'),
 'ncs:occupation:'||s.occupation_code,s.candidate_id,
 jsonb_build_object('result_id',s.result_id,'candidate_id',s.candidate_id,'occupation_code',s.occupation_code,
  'occupation_name',s.occupation_name,'occupation_scheme','NCS','occupation_scheme_run_id',ncs,
  'job_run_id',jobs,'ncs_run_id',ncs,'bundle_id',s.bundle_id,'source_hash',s.source_hash,'binding_hash',s.binding_hash,
  'catalog_hash',s.catalog_hash,'basis','METADATA_INFERRED','assertion_kind','MODEL_INFERRED',
  'item_id',s.item_id,'batch_id',s.batch_id,'attempt_id',s.attempt_id,'model',coalesce(s.actual_model,s.settings->>'categorize_model'),
  'prompt_version',s.settings->>'prompt_version','actor',s.actor,'confidence',NULL,'confidence_state','UNASSESSED',
  'reason',s.reason,'evidence',s.evidence,'role_anchor',s.match->'role_anchor','match_rank',s.match_rank,
  'rank_basis','SOURCE_ANCHOR_DISPLAY_ORDER_V1','original_primary',s.match_rank=1,
  'current_primary',s.match_rank=min(s.match_rank) OVER(PARTITION BY s.result_id),
  'validation_status','VALIDATED','stage','STAGING','accepted',coalesce(s.decision='ACCEPT',false),
  'review_status',CASE WHEN s.decision='ACCEPT' AND s.reviewer_kind='human' THEN 'HUMAN_REVIEWED'
   WHEN s.decision='ACCEPT' THEN 'ASSISTANT_REVIEWED' ELSE 'UNREVIEWED' END,
  'decision_id',s.decision_id,'reviewer',s.reviewer,'reviewer_kind',s.reviewer_kind,'review_notes',s.notes)
 FROM selected s
$$;

CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_candidate_review_packet(batch text)
RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT jsonb_build_object('contract','metadata-occupation-candidate-review-v3','batch_id',batch,
  'rows',coalesce(jsonb_agg(jsonb_build_object('candidate_id',c.candidate_id,'result_id',r.result_id,
   'match_rank',s.match_rank,'occupation_scheme','NCS','occupation_code',c.occupation_code,
   'reason',c.reason,'evidence',c.evidence,'actor',r.actor,'posting_id',i.posting_id,
   'source_fields',enrichment.metadata_occupation_fields(i.source_data),'bundle_id',x.bundle_id,
   'job_run_id',x.job_run_id,'ncs_run_id',x.ncs_run_id,'binding_hash',x.binding_hash,
   'candidates',x.candidates,'review_decision',s.decision,'decision_id',s.decision_id)
   ORDER BY i.ordinal,s.match_rank),'[]'::jsonb))
 FROM enrichment.item i JOIN enrichment.metadata_occupation_binding x USING(item_id)
 JOIN enrichment.metadata_occupation_result r USING(item_id)
 JOIN enrichment.metadata_occupation_candidate c USING(result_id)
 JOIN enrichment.metadata_occupation_candidate_status(r.result_id) s ON s.candidate_id=c.candidate_id
 WHERE i.batch_id=batch
$$;

CREATE OR REPLACE FUNCTION enrichment.bind_metadata_occupation_item(id text,bundle text,candidates jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE i enrichment.item%ROWTYPE; b enrichment.batch%ROWTYPE; ib enrichment.input_bundle%ROWTYPE;
 old enrichment.metadata_occupation_binding%ROWTYPE; metadata text; ch text; bh text; candidate jsonb; expected jsonb;
BEGIN
 PERFORM retention.gate();
 SELECT * INTO STRICT i FROM enrichment.item WHERE item_id=id FOR UPDATE;
 SELECT * INTO STRICT b FROM enrichment.batch WHERE batch_id=i.batch_id;
 SELECT * INTO STRICT ib FROM enrichment.input_bundle WHERE bundle_id=bundle;
 PERFORM enrichment.verify_item_input(id);
 IF b.mode<>'ENRICH' OR b.settings->>'metadata_scope' IS DISTINCT FROM 'NCS_OCCUPATION_INFERENCE_V1'
  OR b.settings->>'acceptance_policy' IS DISTINCT FROM 'REVIEW'
  OR coalesce(b.settings->>'prompt_version','') NOT IN ('ko-metadata-occupation-v1','ko-metadata-occupation-v2','ko-metadata-occupation-v3')
  OR ib.job_run_id<>b.job_run_id OR ib.posting_id<>i.posting_id OR ib.source_hash<>i.source_hash
  OR ib.source_data<>i.source_data OR ib.source_data#>>'{_input,contract}' IS DISTINCT FROM 'jobkorea-input-v1'
  OR NOT EXISTS(SELECT 1 FROM enrichment.item_input WHERE item_id=id AND bundle_id=bundle)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='jobkorea' AND run_id=b.job_run_id)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='ncs_competency' AND run_id=b.ncs_run_id)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_INPUT_BINDING_INVALID'; END IF;
 IF jsonb_typeof(candidates) IS DISTINCT FROM 'array' OR jsonb_array_length(candidates)>30
  OR jsonb_array_length(candidates)<>(SELECT count(DISTINCT x->>'occupation_code') FROM jsonb_array_elements(candidates) x)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATES_INVALID'; END IF;
 metadata:=enrichment.hash(enrichment.metadata_occupation_fields(i.source_data)::text);
 ch:=enrichment.hash(candidates::text);
 bh:=enrichment.hash(jsonb_build_array('metadata-occupation-binding-v1',b.job_run_id,b.ncs_run_id,bundle,i.source_hash,metadata,ch)::text);
 SELECT * INTO old FROM enrichment.metadata_occupation_binding WHERE item_id=id;
 IF FOUND THEN
  -- Existing items replay their original context exactly, including the five
  -- pre-correction paid results; never reinterpret them against the new view.
  IF old.candidates<>candidates THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATE_CHANGED'; END IF;
  IF old.bundle_id<>bundle OR old.binding_hash<>bh OR old.source_hash<>i.source_hash
   OR old.metadata_hash<>metadata OR old.candidates_hash<>ch
  THEN RAISE EXCEPTION 'METADATA_OCCUPATION_BINDING_CHANGED'; END IF;
  RETURN jsonb_build_object('item_id',id,'bundle_id',bundle,'source_hash',i.source_hash,
   'metadata_hash',metadata,'candidates_hash',ch,'binding_hash',bh);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_catalog_context
  WHERE ncs_run_id=b.ncs_run_id AND catalog_context_hash=b.ncs_hash)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_BATCH_CONTEXT_CHANGED'; END IF;
 FOR candidate IN SELECT value FROM jsonb_array_elements(candidates) LOOP
  SELECT jsonb_build_object('occupation_code',c.occupation_code,'occupation_name',c.occupation_name,
   'classification_names',k.classification_names,'unit_names',c.unit_names,'catalog_hash',k.context_hash)
  INTO expected FROM enrichment.metadata_occupation_catalog c
  JOIN enrichment.metadata_occupation_catalog_context k USING(ncs_run_id,occupation_code)
  WHERE c.ncs_run_id=b.ncs_run_id AND c.occupation_code=candidate->>'occupation_code';
  IF expected IS NULL OR candidate-'retrieval_score'<>expected
  THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATE_CHANGED'; END IF;
 END LOOP;
 INSERT INTO enrichment.metadata_occupation_binding(item_id,bundle_id,job_run_id,ncs_run_id,source_hash,metadata_hash,candidates,candidates_hash,binding_hash)
 VALUES(id,bundle,b.job_run_id,b.ncs_run_id,i.source_hash,metadata,candidates,ch,bh) ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('item_id',id,'bundle_id',bundle,'source_hash',i.source_hash,
  'metadata_hash',metadata,'candidates_hash',ch,'binding_hash',bh);
END $$;
CREATE OR REPLACE FUNCTION enrichment.plan_metadata_occupation_batch(id text,jobs text,ncs text,opts jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE j text; n text; nh text; plan_settings jsonb; selected text[]; source record;
 i text; a text; candidates jsonb; binding jsonb; data jsonb; request jsonb; schema jsonb;
 p enrichment.prompt%ROWTYPE; cache text; reused text; status text; ordinal integer:=0; catalog jsonb; requested_prompt text:=coalesce(opts->>'prompt_version','ko-metadata-occupation-v1'); requested_retrieval text:=nullif(opts->>'retrieval_revision','');
BEGIN
 PERFORM retention.gate();
 IF requested_prompt NOT IN ('ko-metadata-occupation-v1','ko-metadata-occupation-v2','ko-metadata-occupation-v3') THEN RAISE EXCEPTION 'INVALID_METADATA_PROMPT_VERSION'; END IF;
 IF requested_retrieval IS NOT NULL AND requested_retrieval<>'metadata-occupation-lexical-v3' THEN RAISE EXCEPTION 'INVALID_METADATA_RETRIEVAL_REVISION'; END IF;
 IF requested_retrieval IS NULL THEN opts:=opts-'retrieval_revision'; END IF;
 IF id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$' OR jsonb_typeof(opts) IS DISTINCT FROM 'object' OR
 NOT opts ?& ARRAY['categorize_model','extra_params','limit','candidate_limit','max_matches',
 'max_input_chars','max_output_tokens','max_requests','request_reserve_usd','max_cost_usd','daily_budget_usd',
 'request_delay_ms','read_timeout_ms','execute_requests','reuse_cache','endpoint'] OR
 (opts->>'limit')::integer NOT BETWEEN 1 AND 10000 OR
 (opts->>'candidate_limit')::integer NOT BETWEEN 1 AND 30 OR
 (opts->>'max_matches')::integer NOT BETWEEN 1 AND (CASE WHEN requested_prompt='ko-metadata-occupation-v3' THEN 3 ELSE 2 END) OR
 (opts->>'max_input_chars')::integer NOT BETWEEN 1000 AND 100000 OR
 (opts->>'max_output_tokens')::integer NOT BETWEEN 256 AND 2048 OR
 (opts->>'max_requests')::integer NOT BETWEEN 1 AND 10000 OR
 (opts->>'request_reserve_usd')::numeric NOT BETWEEN 0.001 AND 1 OR
 (opts->>'max_cost_usd')::numeric NOT BETWEEN 0.001 AND 50 OR
 (opts->>'daily_budget_usd')::numeric NOT BETWEEN 0.001 AND 50 OR
 (opts->>'request_delay_ms')::integer NOT BETWEEN 0 AND 60000 OR
 (opts->>'read_timeout_ms')::integer NOT BETWEEN 1000 AND 600000 OR
 opts->>'execute_requests' NOT IN ('Y','N') OR opts->>'reuse_cache' NOT IN ('Y','N') OR
 nullif(opts->>'categorize_model','') IS NULL OR
 (opts->>'endpoint' IS DISTINCT FROM 'https://openrouter.ai/api/v1/chat/completions' AND
  NOT(coalesce(current_setting('jobtology.isolated_fixture',true),'') ~ '^[0-9a-f]{12}$' AND
   opts->>'endpoint' ~ ('^http://jobtology-jobkorea-test-'||current_setting('jobtology.isolated_fixture',true)||'-mock:[0-9]{1,5}/chat/completions$')
   AND opts->>'categorize_model'='fixture/metadata'))
 THEN RAISE EXCEPTION 'INVALID_METADATA_OCCUPATION_OPTIONS'; END IF;
 IF opts->>'endpoint'='https://openrouter.ai/api/v1/chat/completions' AND
  (opts->>'categorize_model' IS DISTINCT FROM 'openai/gpt-5.6-luna' OR opts->>'provider_only' IS DISTINCT FROM 'openai')
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REQUIRES_PRICED_MODEL_AND_PROVIDER'; END IF;
 IF opts->>'temperature' IS NOT NULL AND (opts->>'temperature')::numeric NOT BETWEEN 0 AND 2
 THEN RAISE EXCEPTION 'INVALID_TEMPERATURE'; END IF;
 IF opts->>'reasoning_effort' IS NOT NULL AND opts->>'reasoning_effort' NOT IN ('none','minimal','low','medium','high')
 THEN RAISE EXCEPTION 'INVALID_REASONING_EFFORT'; END IF;
 IF opts ? 'provider_only' AND (jsonb_typeof(opts->'provider_only') IS DISTINCT FROM 'string' OR
  opts->>'provider_only' !~ '^[a-z0-9][a-z0-9_./-]{0,127}$')
 THEN RAISE EXCEPTION 'INVALID_PROVIDER_SLUG'; END IF;
 IF jsonb_typeof(opts->'extra_params') IS DISTINCT FROM 'object' OR EXISTS(
 SELECT 1 FROM jsonb_object_keys(opts->'extra_params') k WHERE k NOT IN ('top_p','seed','frequency_penalty','presence_penalty')) OR
 EXISTS(SELECT 1 FROM jsonb_each(opts->'extra_params') WHERE jsonb_typeof(value)<>'number') OR
 coalesce((opts#>>'{extra_params,top_p}')::numeric,1) NOT BETWEEN 0 AND 1 OR
 coalesce((opts#>>'{extra_params,frequency_penalty}')::numeric,0) NOT BETWEEN -2 AND 2 OR
 coalesce((opts#>>'{extra_params,presence_penalty}')::numeric,0) NOT BETWEEN -2 AND 2
 THEN RAISE EXCEPTION 'INVALID_EXTRA_PARAMS'; END IF;
 IF nullif(opts->>'posting_ids','') IS NOT NULL THEN
  selected:=string_to_array(opts->>'posting_ids','|');
  IF cardinality(selected)=0 OR cardinality(selected)>(opts->>'limit')::integer OR
   cardinality(selected)<>(SELECT count(DISTINCT v) FROM unnest(selected) v) OR
   EXISTS(SELECT 1 FROM unnest(selected) v WHERE v !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$')
  THEN RAISE EXCEPTION 'INVALID_POSTING_SELECTION'; END IF;
 END IF;
 j:=enrichment.resolve_snapshot(jobs,'jobkorea'); n:=enrichment.resolve_snapshot(ncs,'ncs_competency');
 catalog:=enrichment.prepare_metadata_occupation_catalog(n);
 nh:=catalog->>'catalog_hash';
 IF nh IS NULL THEN RAISE EXCEPTION 'EMPTY_NCS_CATALOG'; END IF;
 plan_settings:=opts||jsonb_build_object('metadata_scope','NCS_OCCUPATION_INFERENCE_V1','prompt_version',requested_prompt,
  'job_source_id','jobkorea','extract_model','unused/metadata-only','acceptance_policy','REVIEW');
 PERFORM pg_advisory_xact_lock(hashtextextended('metadata-occupation-batch:'||id,0));
 IF EXISTS(SELECT 1 FROM enrichment.batch WHERE batch_id=id) THEN
  IF NOT EXISTS(SELECT 1 FROM enrichment.batch existing WHERE existing.batch_id=id AND existing.job_run_id=j AND existing.ncs_run_id=n AND existing.settings=plan_settings)
  THEN RAISE EXCEPTION 'METADATA_BATCH_IS_IMMUTABLE'; END IF;
  RETURN jsonb_build_object('batch_id',id,'job_run_id',j,'ncs_run_id',n,'replay',true);
 END IF;
 SELECT * INTO STRICT p FROM enrichment.prompt WHERE version=requested_prompt AND stage='categorize';
 INSERT INTO enrichment.batch(batch_id,mode,job_run_id,ncs_run_id,ncs_hash,settings,state)
 VALUES(id,'ENRICH',j,n,nh,plan_settings,CASE WHEN opts->>'execute_requests'='Y' THEN 'RUNNING' ELSE 'PLANNED' END);
 FOR source IN SELECT DISTINCT ON (b.posting_id) b.* FROM enrichment.input_bundle b
 WHERE b.job_run_id=j AND b.source_data#>>'{_input,contract}'='jobkorea-input-v1'
 AND (selected IS NULL OR b.posting_id=ANY(selected))
 AND (selected IS NOT NULL OR NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_binding prior
  JOIN enrichment.item old ON old.item_id=prior.item_id
  JOIN enrichment.attempt oa ON oa.attempt_id=old.categorization_id
  WHERE prior.job_run_id=j AND prior.ncs_run_id=n AND old.posting_id=b.posting_id AND prior.source_hash=b.source_hash
  AND (oa.state IN ('VALIDATED','SKIPPED') OR oa.reserved_at IS NOT NULL)))
 ORDER BY b.posting_id,b.created_at,b.bundle_id LIMIT (opts->>'limit')::integer LOOP
  PERFORM enrichment.verify_input_bundle(source.bundle_id);
  ordinal:=ordinal+1; i:=gen_random_uuid()::text; a:=gen_random_uuid()::text;
  INSERT INTO enrichment.item(item_id,batch_id,posting_id,source_data,source_hash,ordinal)
  VALUES(i,id,source.posting_id,source.source_data,source.source_hash,ordinal);
  INSERT INTO enrichment.item_input(item_id,bundle_id) VALUES(i,source.bundle_id);
  candidates:=CASE WHEN requested_retrieval IS NULL
   THEN enrichment.metadata_occupation_candidates(n,source.source_data,(opts->>'candidate_limit')::integer)
   ELSE enrichment.metadata_occupation_candidates_v3(n,source.source_data,(opts->>'candidate_limit')::integer) END;
  binding:=enrichment.bind_metadata_occupation_item(i,source.bundle_id,candidates);
  schema:=p.output_schema;
  schema:=jsonb_set(schema,'{properties,matches,maxItems}',to_jsonb((opts->>'max_matches')::integer));
  IF jsonb_array_length(candidates)>0 THEN
   schema:=jsonb_set(schema,'{properties,matches,items,properties,occupation_code}',jsonb_build_object('type','string','enum',
    (SELECT jsonb_agg(c->'occupation_code') FROM jsonb_array_elements(candidates) c)));
  ELSE schema:=jsonb_set(schema,'{properties,matches,maxItems}','0'); END IF;
  data:=jsonb_build_object('metadata',enrichment.metadata_occupation_fields(source.source_data),
   'candidates',(SELECT coalesce(jsonb_agg(jsonb_build_object('occupation_code',c->'occupation_code',
    'occupation_name',c->'occupation_name','classification_names',c->'classification_names',
    'representative_unit_names',(SELECT coalesce(jsonb_agg(u.value ORDER BY u.ordinal),'[]')
     FROM jsonb_array_elements(c->'unit_names') WITH ORDINALITY u(value,ordinal) WHERE u.ordinal<=3))),'[]')
    FROM jsonb_array_elements(candidates) c),
   'max_matches',(opts->>'max_matches')::integer);
  request:=jsonb_build_object('model',opts->>'categorize_model','messages',jsonb_build_array(
   jsonb_build_object('role','system','content',p.system_prompt),jsonb_build_object('role','user','content',data::text)),
   'response_format',jsonb_build_object('type','json_schema','json_schema',jsonb_build_object('name','jobtology_metadata_occupation','strict',true,'schema',schema)),
   'provider',jsonb_build_object('require_parameters',true,'allow_fallbacks',false,
    'max_price',jsonb_build_object('prompt',0.20,'completion',1.20)),
   'max_tokens',(opts->>'max_output_tokens')::integer,'stream',false)
   || (opts->'extra_params');
  IF opts->>'provider_only' IS NOT NULL THEN request:=jsonb_set(request,'{provider,only}',jsonb_build_array(opts->>'provider_only')); END IF;
  IF opts->>'temperature' IS NOT NULL THEN request:=request||jsonb_build_object('temperature',(opts->>'temperature')::numeric); END IF;
  IF opts->>'reasoning_effort' IS NOT NULL THEN request:=request||jsonb_build_object('reasoning',jsonb_build_object('effort',opts->>'reasoning_effort','exclude',true)); END IF;
  cache:=enrichment.hash(jsonb_build_object('request',request,'prompt_hash',p.content_hash,'endpoint',opts->>'endpoint',
   'metadata_hash',binding->>'metadata_hash','candidates_hash',binding->>'candidates_hash',
   'ncs_hash',nh,'validator',CASE WHEN requested_prompt='ko-metadata-occupation-v3' THEN 'metadata-occupation-v3' ELSE 'metadata-occupation-v1' END,'retriever',coalesce(requested_retrieval,CASE WHEN requested_prompt='ko-metadata-occupation-v1' THEN 'metadata-occupation-lexical-v1' ELSE 'metadata-occupation-lexical-v2' END))::text);
  reused:=NULL;
  IF opts->>'reuse_cache'='Y' THEN
   SELECT old.attempt_id INTO reused FROM enrichment.attempt old JOIN enrichment.batch ob ON ob.batch_id=old.batch_id
   WHERE old.cache_key=cache AND (old.state='VALIDATED' OR (old.batch_id=id AND old.state='PLANNED'))
   AND ob.settings->>'metadata_scope'='NCS_OCCUPATION_INFERENCE_V1'
   AND NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_result r
    JOIN LATERAL(SELECT decision FROM enrichment.metadata_occupation_decision d WHERE d.result_id=r.result_id ORDER BY decision_id DESC LIMIT 1) d ON true
    WHERE r.attempt_id=old.attempt_id AND d.decision='REJECT')
   AND NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_result r JOIN enrichment.metadata_occupation_candidate c USING(result_id)
    JOIN LATERAL(SELECT decision FROM enrichment.metadata_occupation_candidate_decision d WHERE d.candidate_id=c.candidate_id ORDER BY decision_id DESC LIMIT 1) d ON true
    WHERE r.attempt_id=old.attempt_id AND d.decision='REJECT')
   ORDER BY old.completed_at DESC,old.attempt_id LIMIT 1;
  END IF;
  IF reused IS NOT NULL THEN a:=reused;
  ELSE
   status:=CASE WHEN jsonb_array_length(candidates)=0 THEN 'SKIPPED' ELSE 'PLANNED' END;
   request:=request||jsonb_build_object('session_id',id,'trace',jsonb_build_object('trace_id',replace(i,'-',''),
    'trace_name','JobKorea inferred occupation','span_name','metadata_occupation','environment','staging',
    'release',requested_prompt,'posting_id',source.posting_id,'batch_id',id,'attempt_id',a,
    'job_run_id',j,'ncs_run_id',n,'source_bundle_id',source.bundle_id,'binding_hash',binding->>'binding_hash'));
   IF status<>'SKIPPED' AND (length(request::text)>(opts->>'max_input_chars')::integer OR octet_length(request::text)+256>=272000 OR
    1.05*(0.25*(octet_length(request::text)+256)+1.20*(opts->>'max_output_tokens')::integer)/1000000
     >(opts->>'request_reserve_usd')::numeric) THEN status:='REJECTED'; END IF;
   INSERT INTO enrichment.attempt(attempt_id,batch_id,item_id,stage,cache_key,request_body,candidates,state,parsed_output,issues,completed_at)
   VALUES(a,id,i,'categorize',cache,request,candidates,status,
    CASE WHEN status='SKIPPED' THEN jsonb_build_object('outcome','abstained','matches','[]'::jsonb,'abstain_reason','No occupation candidates retrieved from supplied metadata.') END,
    CASE WHEN status='SKIPPED' THEN '["NO_METADATA_OCCUPATION_CANDIDATES"]'::jsonb WHEN status='REJECTED' THEN '["INPUT_OR_COST_BOUND_EXCEEDED"]'::jsonb ELSE '[]'::jsonb END,
    CASE WHEN status IN ('SKIPPED','REJECTED') THEN clock_timestamp() END);
  END IF;
  UPDATE enrichment.item SET categorization_id=a WHERE item_id=i;
 END LOOP;
 IF selected IS NOT NULL AND ordinal<>cardinality(selected) THEN RAISE EXCEPTION 'INCOMPLETE_FROZEN_METADATA_SELECTION'; END IF;
 RETURN jsonb_build_object('batch_id',id,'job_run_id',j,'ncs_run_id',n,'postings',ordinal,'metadata_scope','NCS_OCCUPATION_INFERENCE_V1',
  'planned_requests',(SELECT count(*) FROM enrichment.attempt WHERE batch_id=id AND state='PLANNED'),
  'no_candidate_abstentions',(SELECT count(*) FROM enrichment.attempt WHERE batch_id=id AND state='SKIPPED'));
END $$;
CREATE OR REPLACE FUNCTION enrichment.save_response(aid text, status integer, body text, elapsed bigint)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE a enrichment.attempt%ROWTYPE; b enrichment.batch%ROWTYPE; i enrichment.item%ROWTYPE;
 envelope jsonb; output jsonb; provider_output jsonb; ext jsonb; errors jsonb:='[]'; content text; schema jsonb;
 normalized jsonb; normalization_note jsonb:='{}'::jsonb; removed integer;
 prompt_count bigint; output_count bigint; charged numeric; problem text;
BEGIN
 SELECT * INTO STRICT a FROM enrichment.attempt WHERE attempt_id=aid FOR UPDATE;
 IF a.state<>'RESERVED' THEN RAISE EXCEPTION 'RESPONSE_WITHOUT_RESERVATION'; END IF;
 SELECT * INTO STRICT b FROM enrichment.batch WHERE batch_id=a.batch_id;
 SELECT * INTO STRICT i FROM enrichment.item WHERE item_id=a.item_id;
 IF status=0 THEN errors:='["TRANSPORT_ERROR_UNKNOWN_CHARGE"]';
 ELSIF octet_length(body)>8388608 THEN errors:='["RESPONSE_TOO_LARGE"]';
 ELSE
  BEGIN
   IF NOT coalesce(body IS JSON OBJECT WITH UNIQUE KEYS,false) THEN RAISE EXCEPTION 'INVALID_JSON'; END IF;
   envelope:=body::jsonb;
  EXCEPTION WHEN OTHERS THEN errors:='["INVALID_RESPONSE_JSON"]'; END;
  IF envelope IS NOT NULL THEN
   IF status<>200 OR envelope ? 'error' THEN errors:=errors||'["PROVIDER_ERROR"]'::jsonb;
   ELSIF jsonb_typeof(envelope->'choices') IS DISTINCT FROM 'array' THEN errors:=errors||'["MISSING_CHOICES"]'::jsonb;
   ELSIF jsonb_array_length(envelope->'choices')<>1 OR envelope#>>'{choices,0,finish_reason}' IS DISTINCT FROM 'stop'
     OR coalesce(envelope#>>'{choices,0,message,refusal}','')<>'' THEN errors:=errors||'["INCOMPLETE_OR_REFUSED"]'::jsonb;
   ELSE
    content:=envelope#>>'{choices,0,message,content}';
    BEGIN
     IF NOT coalesce(content IS JSON OBJECT WITH UNIQUE KEYS,false) THEN RAISE EXCEPTION 'INVALID_JSON'; END IF;
     output:=content::jsonb; provider_output:=output;
    EXCEPTION WHEN OTHERS THEN errors:=errors||'["INVALID_OUTPUT_JSON"]'::jsonb; END;
   END IF;
   BEGIN
    IF envelope#>>'{usage,prompt_tokens}' ~ '^[0-9]{1,12}$' THEN prompt_count:=(envelope#>>'{usage,prompt_tokens}')::bigint; END IF;
    IF envelope#>>'{usage,completion_tokens}' ~ '^[0-9]{1,12}$' THEN output_count:=(envelope#>>'{usage,completion_tokens}')::bigint; END IF;
    charged:=enrichment.response_cost(envelope);
   EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
 END IF;
 IF b.settings->>'input_kind'='accepted_revision' THEN
  problem:=enrichment.revision_input_issue(i.item_id);
  IF problem IS NOT NULL THEN errors:=errors||jsonb_build_array(problem); END IF;
 END IF;
 IF output IS NOT NULL AND errors='[]' THEN
  schema:=a.request_body#>'{response_format,json_schema,schema}';
  errors:=CASE WHEN schema->>'description'='jobtology:link-bound-v1' AND a.stage='extract'
   THEN enrichment.schema_issues(output,(SELECT output_schema FROM enrichment.prompt
    WHERE version=b.settings->>'prompt_version' AND stage='extract'))
   -- Source-bound citation IDs and field ownership are checked independently by
   -- output_issues_link_v1 below, avoiding repeated long regex scans on documents.
   WHEN schema->>'description'='jobtology:link-bound-v1' AND a.stage='categorize'
   THEN enrichment.schema_issues(output,schema)
   WHEN schema->>'description'='jobtology:source-bound-ranges-v1'
   THEN enrichment.schema_issues_request_v1(output,schema)
   WHEN b.settings->>'prompt_version' IN ('ko-v6','ko-v7') THEN enrichment.schema_issues_v6(output,schema)
   ELSE enrichment.schema_issues(output,schema) END;
  IF errors='[]' THEN
   IF a.stage='categorize' AND schema->>'description'='jobtology:link-bound-v1'
    AND jsonb_typeof(output->'matches')='array' THEN
    normalized:=enrichment.dedup_exact_matches_v1(output);
    removed:=jsonb_array_length(output->'matches')-jsonb_array_length(normalized->'matches');
    IF removed>0 THEN
     output:=normalized;
     normalization_note:=jsonb_build_object('policy','exact-match-object-dedup-v1','removed',removed);
    END IF;
   END IF;
   IF b.settings->>'input_kind'='accepted_revision' THEN
    SELECT r.extraction INTO STRICT ext FROM enrichment.revision_input binding JOIN enrichment.extraction_revision r USING(revision_id)
    WHERE binding.item_id=i.item_id;
   ELSE SELECT parsed_output INTO ext FROM enrichment.attempt WHERE attempt_id=i.extraction_id; END IF;
   IF b.settings->>'metadata_scope'='NCS_OCCUPATION_INFERENCE_V1' THEN
    IF a.stage<>'categorize' OR i.extraction_id IS NOT NULL THEN
     errors:='["INVALID_METADATA_OCCUPATION_STAGE"]'::jsonb;
    ELSE
     errors:=CASE WHEN b.settings->>'prompt_version'='ko-metadata-occupation-v3'
      THEN enrichment.metadata_occupation_output_issues_v3(output,i.source_data,a.candidates,(b.settings->>'max_matches')::integer)
      ELSE enrichment.metadata_occupation_output_issues(output,i.source_data,a.candidates,(b.settings->>'max_matches')::integer) END;
    END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-v7' THEN
    errors:=enrichment.output_issues_v7(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_v7(output,i.source_data); END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-v6' THEN
    errors:=enrichment.output_issues_v6(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_v6(output,i.source_data); END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-v5' THEN
    errors:=enrichment.output_issues_v5(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_v5(output,i.source_data); END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-v4' THEN
    errors:=enrichment.output_issues_v4(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_v4(output,i.source_data); END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-link-v1' THEN
    errors:=enrichment.output_issues_link_v1(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_link_v1(output,i.source_data); END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-v3' THEN
    errors:=enrichment.output_issues_v3(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_v3(output,i.source_data); END IF;
   ELSIF a.stage='extract' AND b.settings->>'prompt_version'='ko-v2' THEN
    errors:=enrichment.output_issues_v2(output,i.source_data);
    IF errors='[]' THEN output:=enrichment.hydrate_v2(output,i.source_data); END IF;
   ELSE
    errors:=enrichment.output_issues(a.stage,output,i.source_data,ext,a.candidates,(b.settings->>'max_matches')::integer);
   END IF;
  END IF;
 END IF;
 UPDATE enrichment.attempt SET state=CASE WHEN errors='[]' THEN 'VALIDATED' WHEN status=0 OR status<>200 THEN 'ERROR' ELSE 'REJECTED' END,
  http_status=status,response_body=CASE WHEN octet_length(body)<=8388608 THEN body END,
  response_id=envelope->>'id',actual_model=envelope->>'model',provider=envelope->>'provider',
  parsed_output=output,raw_output=provider_output,normalization=normalization_note,issues=errors,prompt_tokens=prompt_count,completion_tokens=output_count,cost_usd=charged,
  latency_ms=elapsed,completed_at=clock_timestamp() WHERE attempt_id=aid;
END $$;
CREATE OR REPLACE FUNCTION enrichment.capture_metadata_occupation_result(id text,actor text)
RETURNS text LANGUAGE plpgsql AS $$
DECLARE i enrichment.item%ROWTYPE; binding enrichment.metadata_occupation_binding%ROWTYPE;
 a enrichment.attempt%ROWTYPE; b enrichment.batch%ROWTYPE; result text; errors jsonb; match jsonb; spans jsonb;
BEGIN
 PERFORM retention.gate();
 IF nullif(btrim(actor),'') IS NULL THEN RAISE EXCEPTION 'METADATA_OCCUPATION_ACTOR_REQUIRED'; END IF;
 SELECT * INTO STRICT i FROM enrichment.item WHERE item_id=id FOR UPDATE;
 SELECT * INTO STRICT b FROM enrichment.batch WHERE batch_id=i.batch_id;
 SELECT * INTO STRICT binding FROM enrichment.metadata_occupation_binding WHERE item_id=id;
 SELECT * INTO STRICT a FROM enrichment.attempt WHERE attempt_id=i.categorization_id;
 PERFORM enrichment.verify_item_input(id);
 IF a.state NOT IN('VALIDATED','SKIPPED') OR a.stage<>'categorize'
  OR a.candidates<>binding.candidates
  OR NOT EXISTS(SELECT 1 FROM enrichment.item original JOIN enrichment.batch batch USING(batch_id)
   WHERE original.item_id=a.item_id
    AND enrichment.metadata_occupation_fields(original.source_data)=enrichment.metadata_occupation_fields(i.source_data)
    AND batch.ncs_run_id=binding.ncs_run_id
    AND batch.settings->>'metadata_scope'='NCS_OCCUPATION_INFERENCE_V1')
  OR (a.state='SKIPPED' AND (binding.candidates<>'[]'::jsonb OR a.parsed_output->>'outcome'<>'abstained'))
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_RESULT_NOT_VALIDATED'; END IF;
 errors:=CASE WHEN b.settings->>'prompt_version'='ko-metadata-occupation-v3'
  THEN enrichment.metadata_occupation_output_issues_v3(a.parsed_output,i.source_data,binding.candidates,(b.settings->>'max_matches')::integer)
  ELSE enrichment.metadata_occupation_output_issues(a.parsed_output,i.source_data,binding.candidates,2) END;
 IF errors<>'[]'::jsonb THEN RAISE EXCEPTION 'METADATA_OCCUPATION_INVALID_OUTPUT: %',errors; END IF;
 result:=enrichment.hash(jsonb_build_array('metadata-occupation-result-v1',id,binding.binding_hash,a.attempt_id,a.parsed_output)::text);
 IF EXISTS(SELECT 1 FROM enrichment.metadata_occupation_result WHERE item_id=id AND result_id<>result)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_RESULT_CHANGED'; END IF;
 INSERT INTO enrichment.metadata_occupation_result(result_id,item_id,attempt_id,output,actor)
 VALUES(result,id,a.attempt_id,a.parsed_output,actor) ON CONFLICT DO NOTHING;
 FOR match IN SELECT value FROM jsonb_array_elements(a.parsed_output->'matches') LOOP
  SELECT jsonb_agg(e||jsonb_build_object('start',position(e->>'quote' in i.source_data->>(e->>'field')),
   'end',position(e->>'quote' in i.source_data->>(e->>'field'))+length(e->>'quote')-1,
   'offset_unit','unicode-codepoint-one-inclusive','source_hash',i.source_hash,'bundle_id',binding.bundle_id,
   'evidence_role','LISTING_METADATA','occurrence_policy','FIRST_EXACT_OCCURRENCE') ORDER BY ordinal)
  INTO spans FROM jsonb_array_elements(match->'evidence') WITH ORDINALITY x(e,ordinal);
  INSERT INTO enrichment.metadata_occupation_candidate(candidate_id,result_id,ncs_run_id,occupation_code,reason,evidence)
  VALUES(enrichment.hash(jsonb_build_array(result,match->>'occupation_code')::text),result,binding.ncs_run_id,
   match->>'occupation_code',match->>'reason',spans) ON CONFLICT DO NOTHING;
 END LOOP;
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION enrichment.decide_metadata_occupation(
 result text,decision text,reviewer text,kind text,notes text)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE r enrichment.metadata_occupation_result%ROWTYPE; id bigint; old enrichment.metadata_occupation_decision%ROWTYPE;
 binding enrichment.metadata_occupation_binding%ROWTYPE;
BEGIN
 PERFORM retention.gate();
 SELECT * INTO STRICT r FROM enrichment.metadata_occupation_result WHERE result_id=result FOR UPDATE;
 IF EXISTS(SELECT 1 FROM enrichment.item i JOIN enrichment.batch b USING(batch_id) WHERE i.item_id=r.item_id AND b.settings->>'prompt_version'='ko-metadata-occupation-v3') THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATE_REVIEW_REQUIRED'; END IF;
 SELECT * INTO STRICT binding FROM enrichment.metadata_occupation_binding WHERE item_id=r.item_id;
 PERFORM enrichment.verify_item_input(r.item_id);
 IF decision NOT IN('ACCEPT','REJECT') OR kind NOT IN('human','assistant')
  OR nullif(btrim(reviewer),'') IS NULL OR nullif(btrim(notes),'') IS NULL
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REVIEW_PROVENANCE_REQUIRED'; END IF;
 IF reviewer=r.actor THEN RAISE EXCEPTION 'METADATA_OCCUPATION_INDEPENDENT_REVIEW_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='jobkorea' AND run_id=binding.job_run_id)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='ncs_competency' AND run_id=binding.ncs_run_id)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REVIEW_SNAPSHOT_STALE'; END IF;
 SELECT * INTO old FROM enrichment.metadata_occupation_decision WHERE result_id=result ORDER BY decision_id DESC LIMIT 1;
 IF FOUND AND old.decision=decision AND old.reviewer=reviewer AND old.reviewer_kind=kind AND old.notes=notes
 THEN RETURN old.decision_id; END IF;
 INSERT INTO enrichment.metadata_occupation_decision(result_id,decision,reviewer,reviewer_kind,notes)
 VALUES(result,decision,reviewer,kind,notes) RETURNING decision_id INTO id;
 RETURN id;
END $$;
CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_graph_rows_legacy(jobs text,ncs text,include_unreviewed boolean DEFAULT false)
RETURNS TABLE(posting_id text,posting_identity text,occupation_identity text,candidate_id text,payload jsonb)
LANGUAGE sql STABLE AS $$
 SELECT s.posting_id,'source:posting:jobkorea:'||enrichment.hash(ib.manifest#>>'{document,source_record_id}'),
  'ncs:occupation:'||c.occupation_code,c.candidate_id,
  jsonb_build_object('result_id',r.result_id,'candidate_id',c.candidate_id,'occupation_code',c.occupation_code,
   'occupation_name',cat.occupation_name,'job_run_id',jobs,'ncs_run_id',ncs,
   'bundle_id',binding.bundle_id,'source_hash',binding.source_hash,'binding_hash',binding.binding_hash,
   'catalog_hash',cat.catalog_hash,'basis','METADATA_INFERRED','assertion_kind','MODEL_INFERRED',
   'item_id',i.item_id,'batch_id',i.batch_id,'attempt_id',r.attempt_id,
   'model',coalesce(a.actual_model,b.settings->>'categorize_model'),
   'prompt_version',b.settings->>'prompt_version','actor',r.actor,
   'confidence',NULL,'confidence_state','UNASSESSED','reason',c.reason,'evidence',c.evidence,
   'validation_status','VALIDATED','stage','STAGING','accepted',coalesce(d.decision='ACCEPT',false),
   'review_status',CASE WHEN d.decision='ACCEPT' AND d.reviewer_kind='human' THEN 'HUMAN_REVIEWED'
     WHEN d.decision='ACCEPT' THEN 'ASSISTANT_REVIEWED' ELSE 'UNREVIEWED' END,
   'decision_id',d.decision_id,'reviewer',d.reviewer,'reviewer_kind',d.reviewer_kind,'review_notes',d.notes)
 FROM enrichment.metadata_occupation_publication_results(jobs,ncs) s
 JOIN enrichment.metadata_occupation_result r ON r.result_id=s.result_id
 JOIN enrichment.metadata_occupation_binding binding ON binding.item_id=s.item_id
 JOIN enrichment.item i ON i.item_id=binding.item_id
 JOIN enrichment.batch b ON b.batch_id=i.batch_id
 JOIN enrichment.attempt a ON a.attempt_id=r.attempt_id
 JOIN enrichment.input_bundle ib ON ib.bundle_id=binding.bundle_id
 JOIN enrichment.metadata_occupation_candidate c ON c.result_id=r.result_id
 JOIN enrichment.metadata_occupation_catalog cat ON cat.ncs_run_id=c.ncs_run_id AND cat.occupation_code=c.occupation_code
 LEFT JOIN LATERAL (SELECT d.* FROM enrichment.metadata_occupation_decision d WHERE d.result_id=r.result_id ORDER BY decision_id DESC LIMIT 1) d ON true
 WHERE b.settings->>'prompt_version'<>'ko-metadata-occupation-v3' AND r.output->>'outcome'='matched' AND d.decision IS DISTINCT FROM 'REJECT'
  AND (d.decision='ACCEPT' OR include_unreviewed)
  AND EXISTS(SELECT 1 FROM ingestion.run WHERE source_id='jobkorea' AND run_id=jobs AND state='READY')
  AND EXISTS(SELECT 1 FROM ingestion.run WHERE source_id='ncs_competency' AND run_id=ncs AND state='READY')
$$;
CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_graph_rows(jobs text,ncs text,include_unreviewed boolean DEFAULT false)
RETURNS TABLE(posting_id text,posting_identity text,occupation_identity text,candidate_id text,payload jsonb)
LANGUAGE sql STABLE AS $$
 SELECT * FROM enrichment.metadata_occupation_graph_rows_legacy(jobs,ncs,include_unreviewed)
 UNION ALL SELECT * FROM enrichment.metadata_occupation_graph_rows_v3(jobs,ncs,include_unreviewed)
$$;
CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_status(jobs text,ncs text)
RETURNS TABLE(posting_id text,item_id text,result_id text,outcome text,decision text,matches jsonb)
LANGUAGE sql STABLE AS $$
 SELECT b.posting_id,b.item_id,r.result_id,
  CASE WHEN r.result_id IS NULL THEN
    CASE WHEN a.completed_at IS NOT NULL AND a.state='REJECTED' THEN 'VALIDATION_FAILED'
     WHEN a.completed_at IS NOT NULL AND a.state='ERROR' THEN 'REQUEST_FAILED'
     ELSE 'PENDING' END
   WHEN d.decision='REJECT' THEN 'REJECTED'
   WHEN r.output->>'outcome'='abstained' THEN 'ABSTAINED'
   WHEN d.decision IS NULL AND b.prompt_version='ko-metadata-occupation-v3' AND EXISTS(SELECT 1 FROM enrichment.metadata_occupation_candidate_status(r.result_id) WHERE decision IS NOT NULL) THEN 'PARTIALLY_REVIEWED'
   WHEN d.decision IS NULL THEN 'REVIEW_PENDING' ELSE 'ACCEPTED_INFERRED_OCCUPATION' END,
  d.decision,coalesce(r.output->'matches','[]'::jsonb)
 FROM (SELECT DISTINCT ON(i.posting_id) i.posting_id,x.item_id,i.categorization_id,b.settings->>'prompt_version' AS prompt_version FROM enrichment.metadata_occupation_binding x
  JOIN enrichment.item i USING(item_id) JOIN enrichment.batch b USING(batch_id)
  WHERE x.job_run_id=jobs AND x.ncs_run_id=ncs ORDER BY i.posting_id,b.created_at DESC,i.item_id DESC) b
 LEFT JOIN enrichment.metadata_occupation_result r USING(item_id)
 -- Follow the selected item's current pointer, including reused attempts. Older
 -- failures cannot override a newer item's unsent or running categorization.
 LEFT JOIN enrichment.attempt a ON a.attempt_id=b.categorization_id AND a.stage='categorize'
 LEFT JOIN LATERAL (SELECT decision FROM (SELECT d.decision,d.decision_id FROM enrichment.metadata_occupation_decision d WHERE d.result_id=r.result_id AND b.prompt_version<>'ko-metadata-occupation-v3'
  UNION ALL SELECT CASE WHEN bool_and(s.decision='REJECT') AND count(s.decision)=count(*) THEN 'REJECT'
   WHEN count(*) FILTER(WHERE s.decision='ACCEPT')>0 AND count(*) FILTER(WHERE s.decision IS NULL)=0 THEN 'ACCEPT' END,0
   FROM enrichment.metadata_occupation_candidate_status(r.result_id) s WHERE b.prompt_version='ko-metadata-occupation-v3' HAVING count(*)>0) latest ORDER BY decision_id DESC LIMIT 1) d ON true
$$;

COMMIT;
